index 0000000..74dbe07
--- /dev/null
+++ b/apps/birdseye/internal/known/known.go
@@ -0,0 +1,152 @@
+// Package known persists a sorted, deduplicated list of Crow module
+// addresses the user has successfully diff'd or browsed, so future
+// invocations can offer shell-completion and TUI suggestions.
+//
+// The on-disk format is plain text, one ns/name/provider per line,
+// alphabetically sorted, with a trailing newline. Empty or missing
+// file means "no suggestions yet" — not an error.
+//
+// Concurrent writers: last writer wins. Two birdseye processes running
+// simultaneously may each see the file before the other's Rename
+// lands; whichever Rename completes last sets the final contents.
+// Acceptable for a low-frequency, append-only-ish list.
+package known
+
+import (
+	"bufio"
+	"fmt"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+
+	"github.com/immuta/operations/services/crow/pkg/api"
+)
+
+// Path returns the default known-modules file path, honoring
+// os.UserConfigDir() (XDG_CONFIG_HOME on Linux, Application Support on
+// macOS). The directory is NOT created here — Add creates it lazily on
+// first write.
+func Path() (string, error) {
+	cfg, err := os.UserConfigDir()
+	if err != nil {
+		return "", fmt.Errorf("resolve user config dir: %w", err)
+	}
+	return filepath.Join(cfg, "birdseye", "known-modules"), nil
+}
+
+// Load reads the file at path. Returns an empty slice if the file
+// does not exist (first run is normal). Lines failing the
+// ns/name/provider validation are silently skipped. The result is
+// sorted ascending.
+func Load(path string) ([]string, error) {
+	f, err := os.Open(path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return nil, nil
+		}
+		return nil, fmt.Errorf("open known-modules: %w", err)
+	}
+	defer f.Close()
+
+	var out []string
+	scanner := bufio.NewScanner(f)
+	for scanner.Scan() {
+		line := strings.TrimSpace(scanner.Text())
+		if line == "" {
+			continue
+		}
+		if !validAddress(line) {
+			continue
+		}
+		out = append(out, line)
+	}
+	if err := scanner.Err(); err != nil {
+		return nil, fmt.Errorf("scan known-modules: %w", err)
+	}
+	sort.Strings(out)
+	return out, nil
+}
+
+// Add inserts address into the file at path. Existing entries are
+// preserved; duplicates deduplicated; the final list is sorted.
+// Writes are atomic via temp file + rename in the same directory.
+// The directory is created with 0o755 if missing. If address is not a
+// well-formed ns/name/provider triple, Add returns an error without
+// touching the file.
+func Add(path, address string) error {
+	if !validAddress(address) {
+		return fmt.Errorf("invalid module address %q", address)
+	}
+	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
+		return fmt.Errorf("mkdir known-modules dir: %w", err)
+	}
+
+	existing, err := Load(path)
+	if err != nil {
+		return err
+	}
+	merged := mergeAndSort(existing, address)
+
+	tmp, err := os.CreateTemp(filepath.Dir(path), ".known-modules-*.tmp")
+	if err != nil {
+		return fmt.Errorf("create temp: %w", err)
+	}
+	tmpName := tmp.Name()
+	w := bufio.NewWriter(tmp)
+	for _, addr := range merged {
+		if _, err := w.WriteString(addr); err != nil {
+			_ = tmp.Close()
+			_ = os.Remove(tmpName)
+			return fmt.Errorf("write temp: %w", err)
+		}
+		if err := w.WriteByte('\n'); err != nil {
+			_ = tmp.Close()
+			_ = os.Remove(tmpName)
+			return fmt.Errorf("write temp: %w", err)
+		}
+	}
+	if err := w.Flush(); err != nil {
+		_ = tmp.Close()
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("flush temp: %w", err)
+	}
+	if err := tmp.Close(); err != nil {
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("close temp: %w", err)
+	}
+	if err := os.Rename(tmpName, path); err != nil {
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("rename temp: %w", err)
+	}
+	return nil
+}
+
+// mergeAndSort returns a deduplicated, sorted slice combining existing
+// with the new address.
+func mergeAndSort(existing []string, address string) []string {
+	seen := make(map[string]struct{}, len(existing)+1)
+	out := make([]string, 0, len(existing)+1)
+	for _, a := range existing {
+		if _, dup := seen[a]; dup {
+			continue
+		}
+		seen[a] = struct{}{}
+		out = append(out, a)
+	}
+	if _, dup := seen[address]; !dup {
+		out = append(out, address)
+	}
+	sort.Strings(out)
+	return out
+}
+
+// validAddress checks that s is exactly three slash-separated segments
+// each passing api.ValidateSegments.
+func validAddress(s string) bool {
+	parts := strings.Split(s, "/")
+	if len(parts) != 3 {
+		return false
+	}
+	return api.ValidateSegments(parts) == nil
+}
diff --git a/apps/birdseye/internal/known/known_test.go b/apps/birdseye/internal/known/known_test.go
new file mode 100644
index 0000000..cd4ee26
--- /dev/null
+++ b/apps/birdseye/internal/known/known_test.go
@@ -0,0 +1,66 @@
+package known
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+)
+
+func TestLoadMissingFileReturnsEmpty(t *testing.T) {
+	dir := t.TempDir()
+	got, err := Load(filepath.Join(dir, "missing"))
+	if err != nil {
+		t.Fatalf("Load: %v", err)
+	}
+	if len(got) != 0 {
+		t.Errorf("expected empty slice, got %v", got)
+	}
+}
+
+func TestAddCreatesDirectoryAndFile(t *testing.T) {
+	dir := t.TempDir()
+	path := filepath.Join(dir, "subdir", "known-modules")
+	if err := Add(path, "iac/comply/aws"); err != nil {
+		t.Fatalf("Add: %v", err)
+	}
+	body, err := os.ReadFile(path)
+	if err != nil {
+		t.Fatalf("ReadFile: %v", err)
+	}
+	if string(body) != "iac/comply/aws\n" {
+		t.Errorf("body = %q", body)
+	}
+}
+
+func TestAddThenLoadRoundTrip(t *testing.T) {
+	dir := t.TempDir()
+	path := filepath.Join(dir, "known-modules")
+	if err := Add(path, "iac/comply/aws"); err != nil {
+		t.Fatalf("Add: %v", err)
+	}
+	got, err := Load(path)
+	if err != nil {
+		t.Fatalf("Load: %v", err)
+	}
+	if len(got) != 1 || got[0] != "iac/comply/aws" {
+		t.Errorf("Load = %v, want [iac/comply/aws]", got)
+	}
+}
+
+func TestPathHonorsUserConfigDir(t *testing.T) {
+	got, err := Path()
+	if err != nil {
+		t.Fatalf("Path: %v", err)
+	}
+	if !filepath.IsAbs(got) {
+		t.Errorf("expected absolute path, got %q", got)
+	}
+	base := filepath.Base(got)
+	if base != "known-modules" {
+		t.Errorf("expected basename %q, got %q", "known-modules", base)
+	}
+	parent := filepath.Base(filepath.Dir(got))
+	if parent != "birdseye" {
+		t.Errorf("expected parent dir %q, got %q", "birdseye", parent)
+	}
+}
